from math import comb

def path_count(m: int, n: int) -> int:
    if m == 0 or n == 0:
        return 1
    return path_count(m - 1, n) + path_count(m, n - 1)

for m in range(6):
    for n in range(6):
        pc = path_count(m, n)
        assert pc == comb(m + n, n)        # pathCount_eq_choose
        assert pc == path_count(n, m)      # pathCount_symm
print("pathCount = C(m+n,n) and symmetry verified for 0<=m,n<=5")

from math import comb

def vandermonde(m: int, n: int, r: int) -> bool:
    return comb(m + n, r) == sum(comb(m, k) * comb(n, r - k) for k in range(r + 1))

def absorption(n: int, k: int) -> bool:
    return (k + 1) * comb(n + 1, k + 1) == (n + 1) * comb(n, k)

assert all(vandermonde(m, n, r) for (m, n, r) in [(3,4,5),(5,5,3),(6,2,7)])
assert all(absorption(n, k) for (n, k) in [(5,2),(9,4),(10,0)])
print("Vandermonde convolution and absorption identity verified")

from itertools import permutations

def area(p: str) -> int:
    h = a = 0
    for s in p:
        if s == "N":
            h += 1
        else:
            a += h
    return a

def swap_path(p: str) -> str:
    return "".join("N" if s == "E" else "E" for s in p)

def all_paths(m: int, n: int):
    return sorted({"".join(t) for t in permutations("E"*m + "N"*n)})

for (m, n) in [(2,3),(3,3),(4,2)]:
    for p in all_paths(m, n):
        assert area(p) + area(swap_path(p)) == p.count("E") * p.count("N")
        assert swap_path(swap_path(p)) == p
print("area complement and swap involution verified")

from itertools import permutations
from math import comb

def poly_add(a, b):
    out = [0]*max(len(a), len(b))
    for i,c in enumerate(a): out[i]+=c
    for i,c in enumerate(b): out[i]+=c
    return out

def q_binomial(m, n):
    if m == 0 or n == 0:
        return [1]
    return poly_add(q_binomial(m, n-1), [0]*n + q_binomial(m-1, n))

def area(p):
    h=a=0
    for s in p:
        if s=="N": h+=1
        else: a+=h
    return a

def by_area(m, n):
    out=[]
    for t in {"".join(x) for x in permutations("E"*m+"N"*n)}:
        a=area(t)
        if a>=len(out): out += [0]*(a+1-len(out))
        out[a]+=1
    return out or [0]

for (m,n) in [(1,1),(2,1),(2,2),(3,2)]:
    qb=q_binomial(m,n)
    assert qb==by_area(m,n)
    assert sum(qb)==comb(m+n,n)     # eval at q=1
    print(f"[{m+n} choose {n}]_q coeffs = {qb}, sum = {sum(qb)} = C({m+n},{n})")

