function PATH_COUNT_DP(m, n):
    create table T of size (m+1) x (n+1)
    for i in 0..m: T[i][0] <- 1          # straight-east boundary
    for j in 0..n: T[0][j] <- 1          # straight-north boundary
    for i in 1..m:
        for j in 1..n:
            T[i][j] <- T[i-1][j] + T[i][j-1]
    return T[m][n]

